defmodule Board.Fsm.Renderer do
  @moduledoc false

  def document(module, name) do
    "# #{name}\n\nGenerated by `mix board.fsm.docs`. Do not edit by hand.\n\n```mermaid\n" <>
      module.to_mermaid() <> "```\n\n" <> module.matrix()
  end

  def to_mermaid(m) do
    arrows =
      for row <- m.rows,
          row.kind == :transition,
          not (row.to == :stay and elem(row.rank, 0) != 0) do
        from = source(row)
        to = if row.to == :stay, do: from, else: row.to
        label = Enum.map_join(row.events, ", ", &to_string/1) <> guard_text(row.guard)
        fx = effects_text(row.effects)
        "    #{from} --> #{to}: #{escape(label <> if(fx == "", do: "", else: " / " <> fx))}\n"
      end

    groups =
      m.groups
      |> Enum.sort()
      |> Enum.map(fn {name, states} ->
        "    state \"#{name}: #{Enum.join(states, ", ")}\" as #{name}\n"
      end)

    sets =
      for row <- m.rows, row.kind == :transition, is_list(row.from), row.to != :stay do
        "    state \"#{Enum.join(row.from, ", ")}\" as #{source(row)}\n"
      end

    any =
      if Enum.any?(m.rows, &(&1.kind == :transition and &1.from == :any)),
        do: "    state \"any state\" as fsm_any\n",
        else: ""

    state_fx =
      for state <- m.states,
          phase <- [:exit, :enter],
          fx = m.state_effects[state][phase],
          fx != [] do
        "    #{state}: #{phase} / #{escape(effects_text(fx))}\n"
      end

    IO.iodata_to_binary([
      "stateDiagram-v2\n    [*] --> #{m.initial}\n",
      arrows,
      groups,
      sets,
      any,
      state_fx
    ])
  end

  def matrix(m) do
    lines =
      for state <- m.states, event <- m.events, row <- Map.fetch!(m.choices, {state, event}) do
        {result, fx} =
          case row.kind do
            :ignore ->
              {"ignored", []}

            :invalid ->
              {"invalid", []}

            :transition ->
              next = if row.to == :stay, do: state, else: row.to

              fx =
                if next == state,
                  do: row.effects,
                  else: m.state_effects[state].exit ++ row.effects ++ m.state_effects[next].enter

              {if(row.to == :stay, do: "stay", else: "-> #{next}"), fx}
          end

        "| #{state} | #{event}#{guard_text(row.guard)} | #{result} | #{markdown(effects_text(fx))} |\n"
      end

    IO.iodata_to_binary([
      "| state | event | result | effects |\n| --- | --- | --- | --- |\n",
      lines
    ])
  end

  defp source(%{from: :any}), do: "fsm_any"
  defp source(%{from: from, id: id}) when is_list(from), do: "fsm_set_#{id}"
  defp source(%{from: from}), do: from
  defp guard_text(nil), do: ""
  defp guard_text(guard), do: " [#{guard}]"

  defp effects_text(effects),
    do: Enum.map_join(effects, ", ", fn {name, arg} -> "#{name}(#{value(arg)})" end)

  defp value(arg) when is_atom(arg), do: to_string(arg)
  defp value(arg), do: inspect(arg, limit: :infinity, printable_limit: :infinity)
  defp markdown(text), do: text |> String.replace("|", "&#124;") |> String.replace("\n", "<br>")

  defp escape(text),
    do:
      text
      |> String.replace("&", "&amp;")
      |> String.replace("\"", "&quot;")
      |> String.replace("<", "&lt;")
      |> String.replace("\n", " ")
end
